const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Calculate learning completion
const calculateLearningCompletion = async (userId, courseId) => {
  const units = await Unit.find({ courseId });
  const unitIds = units.map((u) => u._id);

  const lessons = await Lesson.find({ unitId: { $in: unitIds } });
  const totalLessons = lessons.length;

  if (totalLessons === 0) return 100;

  const progress = await Progress.findOne({ userId, courseId });
  if (!progress || !progress.completedLessons) return 0;

  const completedLessonIds = progress.completedLessons.map(id => id.toString());
  const validCompletedCount = lessons.filter(l => completedLessonIds.includes(l._id.toString())).length;

  return Math.min(100, (validCompletedCount / totalLessons) * 100);
};

// Calculate assignment average
const calculateAssignmentAverage = async (userId, courseId) => {
  const assignments = await Assignment.find({ courseId, status: "published" });
  if (assignments.length === 0) return { average: 100, hasAssignments: false };

  let totalMaxMarks = 0;
  let totalObtainedMarks = 0;

  for (const assignment of assignments) {
    totalMaxMarks += assignment.maximumMarks;
    const submission = await AssignmentSubmission.findOne({ 
      assignmentId: assignment._id, 
      studentId: userId,
      status: "marked"
    });

    if (submission && submission.marks !== null) {
      totalObtainedMarks += submission.marks;
    }
  }

  if (totalMaxMarks === 0) return { average: 100, hasAssignments: false };

  const average = (totalObtainedMarks / totalMaxMarks) * 100;
  return { average, hasAssignments: true };
};

// Calculate quiz average
const calculateQuizAverage = async (userId, courseId) => {
  const quizzes = await Quiz.find({ courseId, status: "published" });
  if (quizzes.length === 0) return { average: 100, hasQuizzes: false };

  let totalMaxScore = 0;
  let totalObtainedScore = 0;

  for (const quiz of quizzes) {
    const submissions = await QuizSubmission.find({ quizId: quiz._id, studentId: userId }).sort({ totalScore: -1 });
    
    let bestScore = 0;
    // According to QuizSubmission model: totalScore, maxScore
    if (submissions.length > 0) {
      bestScore = submissions[0].totalScore;
      totalMaxScore += submissions[0].maxScore;
    } else {
      // If no submission, we might not have maxScore easily. Defaulting to 100 or lookup.
      // But we must count it against them. Let's assume default 100.
      totalMaxScore += 100; 
    }
    
    totalObtainedScore += bestScore;
  }

  if (totalMaxScore === 0) return { average: 100, hasQuizzes: false };

  const average = (totalObtainedScore / totalMaxScore) * 100;
  return { average, hasQuizzes: true };
};

// GET /api/certificates/eligibility/:courseId
export const checkEligibility = async (req, res) => {
  try {
    const courseId = req.params.courseId;
    const userId = req.user.id || req.user._id;

    const course = await Course.findById(courseId);
    if (!course) return res.status(404).json({ error: "Course not found" });

    const learningCompletion = await calculateLearningCompletion(userId, courseId);
    const assignmentStats = await calculateAssignmentAverage(userId, courseId);
    const quizStats = await calculateQuizAverage(userId, courseId);

    let overallAssessmentAverage = 0;
    if (!assignmentStats.hasAssignments && !quizStats.hasQuizzes) {
      overallAssessmentAverage = 100;
    } else if (!assignmentStats.hasAssignments) {
      overallAssessmentAverage = quizStats.average;
    } else if (!quizStats.hasQuizzes) {
      overallAssessmentAverage = assignmentStats.average;
    } else {
      overallAssessmentAverage = (assignmentStats.average + quizStats.average) / 2;
    }

    const eligible = learningCompletion >= 100 && overallAssessmentAverage >= 50;
    const existingCert = await Certificate.findOne({ studentId: userId, courseId });

    res.json({
      eligible,
      learningCompletion: parseFloat(learningCompletion.toFixed(2)),
      assignmentAverage: parseFloat(assignmentStats.average.toFixed(2)),
      quizAverage: parseFloat(quizStats.average.toFixed(2)),
      overallAssessmentAverage: parseFloat(overallAssessmentAverage.toFixed(2)),
      certificateGenerated: !!existingCert,
      certificate: existingCert || null
    });
  } catch (error) {
    console.error("Eligibility Check Error:", error);
    res.status(500).json({ error: "Failed to check eligibility" });
  }
};

