// POST /api/certificates/generate
export const generateCertificate = async (req, res) => {
  try {
    const { courseId } = req.body;
    const userId = req.user.id || req.user._id;

    const user = await User.findById(userId);
    const course = await Course.findById(courseId);

    if (!user || !course) {
      return res.status(404).json({ error: "User or Course not found" });
    }

    const learningCompletion = await calculateLearningCompletion(userId, courseId);
    const assignmentStats = await calculateAssignmentAverage(userId, courseId);
    const quizStats = await calculateQuizAverage(userId, courseId);
    
    let overallAssessmentAverage = 0;
    if (!assignmentStats.hasAssignments && !quizStats.hasQuizzes) {
      overallAssessmentAverage = 100;
    } else if (!assignmentStats.hasAssignments) {
      overallAssessmentAverage = quizStats.average;
    } else if (!quizStats.hasQuizzes) {
      overallAssessmentAverage = assignmentStats.average;
    } else {
      overallAssessmentAverage = (assignmentStats.average + quizStats.average) / 2;
    }

    const eligible = learningCompletion >= 100 && overallAssessmentAverage >= 50;

    if (!eligible) {
      if (learningCompletion >= 100) {
        const subject = "Course Completion Result - Certificate Not Eligible";
        const html = `
          <p>Dear ${user.name},</p>
          <p>You have completed the learning requirements for: <b>${course.title}</b></p>
          <p>However, your assignment and quiz assessment average is: <b>${overallAssessmentAverage.toFixed(2)}%</b></p>
          <p>The minimum required assessment average for certificate eligibility is: <b>50%</b></p>
          <p>Therefore, you are currently not eligible to receive a course completion certificate.</p>
          <p>You may review your course performance and follow the LMS rules for any available reassessment or retry opportunities.</p>
          <p>Regards,<br>Shnoor International LLC<br>Shnoor LMS</p>
        `;
        sendMail({ to: user.email, subject, html }).catch(err => console.log("Failure email error", err));
      }
      return res.status(403).json({ error: "Not eligible for certificate" });
    }

    let certificate = await Certificate.findOne({ studentId: userId, courseId });
    if (certificate) {
      return res.json({ alreadyGenerated: true, certificate });
    }

    const certId = `SHNOOR-CERT-${new Date().getFullYear()}-${uuidv4().split('-')[0].toUpperCase()}`;
    const completionDateStr = new Date().toLocaleDateString('en-GB', {
      day: 'numeric', month: 'long', year: 'numeric'
    });

    const htmlContent = generateCertificateHTML({
      studentName: user.name,
      courseName: course.title,
      completionDate: completionDateStr,
      certificateId: certId
    });

    const pdfDir = path.join(__dirname, '..', 'public', 'certificates');
    if (!fs.existsSync(pdfDir)) {
      fs.mkdirSync(pdfDir, { recursive: true });
    }
    const pdfFilename = `${certId}.pdf`;
    const pdfPath = path.join(pdfDir, pdfFilename);

    const browser = await puppeteer.launch({ headless: 'new', args: ['--no-sandbox'] });
    const page = await browser.newPage();
    await page.setContent(htmlContent, { waitUntil: 'networkidle0' });
    await page.pdf({
        path: pdfPath,
        format: 'A4',
        landscape: true,
        printBackground: true,
        margin: { top: 0, right: 0, bottom: 0, left: 0 }
      });
      await page.setViewport({ width: 1024, height: 723 });
      await page.screenshot({ path: pdfPath.replace('.pdf', '.jpg'), type: 'jpeg', quality: 90 });
    await browser.close();

    const pdfUrl = `/certificates/${pdfFilename}`;

    certificate = new Certificate({
      certificateId: certId,
      studentId: userId,
      courseId: courseId,
      studentName: user.name,
      studentEmail: user.email,
      courseName: course.title,
      learningCompletion,
      assignmentAverage: assignmentStats.average,
      quizAverage: quizStats.average,
      overallAssessmentAverage,
      pdfUrl,
      status: "generated"
    });

    await certificate.save();

    // Create Notification
    try {
      await createNotification({
        recipient: userId,
        type: 'course_completed',
        title: 'Certificate Generated!',
        message: `Congratulations! Your certificate for "${course.title}" has been successfully generated.`,
        actionUrl: `/student/certificates`,
        dedupeKey: `cert_gen_${certId}`
      });
    } catch(e) {
      console.error('Failed to create cert notification', e);
    }

    const subject = "Congratulations! Your Shnoor Course Certificate is Ready";
    const emailHtml = `
      <p>Dear ${user.name},</p>
      <p>Congratulations!</p>
      <p>You have successfully completed the course: <b>${course.title}</b></p>
      <p>Your certificate of completion has been generated successfully.</p>
      <p>Certificate ID: ${certId}<br>Completion Date: ${completionDateStr}</p>
      <p>Please find your certificate attached to this email. You can also download/view your certificate from your Shnoor LMS dashboard.</p>
      <p>Regards,<br>Shnoor International LLC<br>Shnoor LMS</p>
    `;

    try {
      await sendMail({
        to: user.email,
        subject,
        html: emailHtml,
        attachments: [
          {
            filename: pdfFilename,
            path: pdfPath
          }
        ]
      });
      certificate.status = "email_sent";
      await certificate.save();
    } catch (err) {
      certificate.status = "email_failed";
      await certificate.save();
    }

    res.json({ success: true, certificate });
  } catch (error) {
    console.error("Certificate generation error:", error);
    res.status(500).json({ error: "Failed to generate certificate" });
  }
};

// GET /api/certificates/my-certificates
export const getMyCertificates = async (req, res) => {
  try {
    const userId = req.user.id || req.user._id;
    const certificates = await Certificate.find({ studentId: userId }).sort({ createdAt: -1 });
    res.json(certificates);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch certificates" });
  }
};

// GET /api/certificates/:certificateId
export const getCertificateById = async (req, res) => {
  try {
    const certificate = await Certificate.findOne({ certificateId: req.params.certificateId });
    if (!certificate) return res.status(404).json({ error: "Certificate not found" });
    res.json(certificate);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch certificate" });
  }
};

// GET /api/certificates/admin/all
export const getAllCertificates = async (req, res) => {
  try {
    const certificates = await Certificate.find().sort({ createdAt: -1 });
    res.json(certificates);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch certificates" });
  }
};
